import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 4
    stream = io.StringIO(raw_csv.removeprefix("\ufeff"), newline="")
    records = list(csv.reader(stream, delimiter=",", quotechar='"', doublequote=True))

    nonempty = [
        index for index, record in enumerate(records)
        if any(field.strip() for field in record)
    ]
    if not nonempty:
        return {"columns": [], "rows": []}

    full_width = [
        index for index in nonempty if len(records[index]) == expected_width
    ]
    year = re.compile(r"[0-9]{4}")

    def looks_like_header(record):
        first, earlier, later, last = (field.strip() for field in record)
        return (
            any(char.isalpha() for char in first)
            and any(char.isalpha() for char in last)
            and year.fullmatch(earlier) is not None
            and year.fullmatch(later) is not None
        )

    fallback = full_width[0] if full_width else nonempty[0]
    header_index = next(
        (index for index in full_width if looks_like_header(records[index])),
        fallback,
    )
    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    used_names = set(columns)
    number = 1
    while len(columns) < width:
        name = f"extra_{number}"
        number += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
